@group(0) @binding(2) var<uniform> params : Params;
struct FragInput { @builtin(position) pos: vec4f, @location(0) uv: vec2f }
fn rand(co: vec2f, seed: f32) -> f32 {
    return fract(sin(dot(co, vec2f(12.9898 + seed, 78.233))) * 43758.5453);
}
@fragment
fn fs_main(in: FragInput) -> @location(0) vec4f {
    let color = textureSampleLevel(input_texture, input_sampler, in.uv, 0.0);
    let frame = floor(params.time * 24.0);
    let noise = (rand(in.uv, frame) * 2.0 - 1.0) * params.grain_strength * 0.08;
    return vec4f(clamp(color.rgb + noise, vec3f(0.0), vec3f(1.0)), color.a);
}

