@group(0) @binding(0) var input_texture : texture_2d<f32>;
@group(0) @binding(1) var input_sampler : sampler;
struct Params { time: f32, blur_radius: f32 }
@group(0) @binding(2) var<uniform> params : Params;
struct FragInput { @builtin(position) pos: vec4f, @location(0) uv: vec2f }
@fragment
fn fs_main(in: FragInput) -> @location(0) vec4f {
    let step = params.blur_radius * 0.003;
    var acc  = vec4f(0.0);
    let weights = array<f32, 5>(0.0625, 0.25, 0.375, 0.25, 0.0625);
    let offsets = array<f32, 5>(-2.0, -1.0, 0.0, 1.0, 2.0);
    for (var i = 0; i < 5; i++) {
        for (var j = 0; j < 5; j++) {
            let uv_off = in.uv + vec2f(offsets[i], offsets[j]) * step;
            acc += textureSampleLevel(input_texture, input_sampler, uv_off, 0.0)
                   * weights[i] * weights[j];
        }
    }
    return acc;
}

