precision highp float;
uniform sampler2D u_input_texture;
uniform float u_time;
uniform float u_blur_radius;
in vec2 v_uv;
out vec4 frag_color;
void main() {
    float step = u_blur_radius * 0.003;
    vec4  acc  = vec4(0.0);
    float weights[5];
    weights[0] = 0.0625; weights[1] = 0.25; weights[2] = 0.375;
    weights[3] = 0.25;   weights[4] = 0.0625;
    float offsets[5];
    offsets[0] = -2.0; offsets[1] = -1.0; offsets[2] = 0.0;
    offsets[3] =  1.0; offsets[4] =  2.0;
    for (int i = 0; i < 5; i++) {
        for (int j = 0; j < 5; j++) {
            vec2 uv_off = v_uv + vec2(offsets[i], offsets[j]) * step;
            acc += texture(u_input_texture, uv_off) * weights[i] * weights[j];
        }
    }
    frag_color = acc;
}

