@group(0) @binding(0) var input_texture : texture_2d<f32>;
@group(0) @binding(1) var input_sampler : sampler;
struct Params { time: f32, glitch_amount: f32, tear_frequency: f32 }
@group(0) @binding(2) var<uniform> params : Params;
struct FragInput { @builtin(position) pos: vec4f, @location(0) uv: vec2f }
fn hash(n: f32) -> f32 { return fract(sin(n) * 43758.5453); }
@fragment
fn fs_main(in: FragInput) -> @location(0) vec4f {
    var uv    = in.uv;
    let row   = floor(uv.y * params.tear_frequency);
    let seed  = hash(row + floor(params.time * 8.0) * 0.1);
    let shift = (seed - 0.5) * params.glitch_amount * 0.12;
    if (seed > 0.85) { uv.x = fract(uv.x + shift); }
    let split = params.glitch_amount * 0.008;
    let r = textureSampleLevel(input_texture, input_sampler, uv + vec2f( split, 0.0), 0.0).r;
    let g = textureSampleLevel(input_texture, input_sampler, uv,                       0.0).g;
    let b = textureSampleLevel(input_texture, input_sampler, uv - vec2f( split, 0.0), 0.0).b;
    return vec4f(r, g, b, 1.0);
}

