@group(0) @binding(0) var input_texture : texture_2d<f32>;
@group(0) @binding(1) var input_sampler : sampler;
struct Params { time: f32, sepia_strength: f32, contrast: f32 }
@group(0) @binding(2) var<uniform> params : Params;
struct FragInput { @builtin(position) pos: vec4f, @location(0) uv: vec2f }
@fragment
fn fs_main(in: FragInput) -> @location(0) vec4f {
    let c = textureSampleLevel(input_texture, input_sampler, in.uv, 0.0).rgb;
    let r = dot(c, vec3f(0.393, 0.769, 0.189));
    let g = dot(c, vec3f(0.349, 0.686, 0.168));
    let b = dot(c, vec3f(0.272, 0.534, 0.131));
    let sepia    = clamp(vec3f(r, g, b), vec3f(0.0), vec3f(1.0));
    let contrasted = (sepia - 0.5) * params.contrast + 0.5;
    let result   = mix(c, clamp(contrasted, vec3f(0.0), vec3f(1.0)), params.sepia_strength);
    return vec4f(result, 1.0);
}

