templates.wgsl_skeleton:
@group(0) @binding(0) var input_texture : texture_2d<f32>;
@group(0) @binding(1) var input_sampler : sampler;
struct Params { time: f32, edge_strength: f32, edge_thickness: f32 }
@group(0) @binding(2) var<uniform> params : Params;
struct FragInput { @builtin(position) pos: vec4f, @location(0) uv: vec2f }
fn luma(c: vec3f) -> f32 { return dot(c, vec3f(0.299, 0.587, 0.114)); }
@fragment
fn fs_main(in: FragInput) -> @location(0) vec4f {
    let s   = params.edge_thickness * 0.002;
    let tl  = luma(textureSampleLevel(input_texture, input_sampler, in.uv + vec2f(-s,  s), 0.0).rgb);
    let tc  = luma(textureSampleLevel(input_texture, input_sampler, in.uv + vec2f( 0,  s), 0.0).rgb);
    let tr  = luma(textureSampleLevel(input_texture, input_sampler, in.uv + vec2f( s,  s), 0.0).rgb);
    let ml  = luma(textureSampleLevel(input_texture, input_sampler, in.uv + vec2f(-s,  0), 0.0).rgb);
    let mr  = luma(textureSampleLevel(input_texture, input_sampler, in.uv + vec2f( s,  0), 0.0).rgb);
    let bl  = luma(textureSampleLevel(input_texture, input_sampler, in.uv + vec2f(-s, -s), 0.0).rgb);
    let bc  = luma(textureSampleLevel(input_texture, input_sampler, in.uv + vec2f( 0, -s), 0.0).rgb);
    let br  = luma(textureSampleLevel(input_texture, input_sampler, in.uv + vec2f( s, -s), 0.0).rgb);
    let gx  = -tl - 2.0*ml - bl + tr + 2.0*mr + br;
    let gy  = -tl - 2.0*tc - tr + bl + 2.0*bc + br;
    let edge = clamp(sqrt(gx*gx + gy*gy) * params.edge_strength * 4.0, 0.0, 1.0);
    let orig = textureSampleLevel(input_texture, input_sampler, in.uv, 0.0);
    return vec4f(orig.rgb * (1.0 - edge), orig.a);
}

